-- statistics-base.sql
--
-- Shared fixture for DynamicStatisticsBuilderTest.
-- 7 payroll periods, each a self-contained slice:
--   P1  2026-01-01 … 2026-01-31  MONTHLY   baseline (10 + 1 GBP employee, DEU 4, GBR 4, USA 3)
--   P2  2026-02-01 … 2026-02-28  MONTHLY   mixed currency in one country (ref + convertible + unconvertible)
--   P3  2026-03-01 … 2026-03-31  MONTHLY   known conversion rate (EUR->USD at 0.50)
--   P4  2026-04-01 … 2026-04-30  MONTHLY   empty (no summaries)
--   P5  2026-05-01 … 2026-05-31  MONTHLY   only DRAFT summaries
--   P6  2026-06-01 … 2026-06-30  BI_WEEKLY baseline bi-weekly case (8 employees in GBR + USA)
--   P7  2026-07-01 … 2026-07-31  MONTHLY   noise only (IND, only visible if July is queried)
--
-- Reference currency: USD. currency_rates:
--   1 USD = 1 USD (identity — reference_amount = 1, rate = 1, enforced by trigger)
--   1 USD = 0.50 EUR
--   1 USD = 0.20 GBP
--   XYZ has NO rate — any summary in XYZ is unconvertible.
--
-- UUIDs are deterministic:
--   countries      00000000-0000-4000-a000-0000000001NN
--   departments    00000000-0000-4000-a000-0000000002NN
--   roles          00000000-0000-4000-a000-0000000003NN
--   employees      00000000-0000-4000-a000-0000000004NN
--   assignments    00000000-0000-4000-a000-0000000005NN
--   periods        00000000-0000-4000-a000-0000000006NN
--   summaries      00000000-0000-4000-a000-0000000007NN
--   rates          00000000-0000-4000-a000-0000000008NN
--
-- All totals are computed at scale 2:
--   total = ROUND(base + variable + allowances + employer_taxes, 2)
-- which satisfies the CHECK in V202610281.

DELETE FROM payroll_period_earner_percentiles;
DELETE FROM payroll_period_earner_rankings;
DELETE FROM payroll_period_aggregates;
DELETE FROM payroll_summaries;
DELETE FROM employee_periodic_assignments;
DELETE FROM payroll_periods;
DELETE FROM currency_rates;
DELETE FROM employees;
DELETE FROM roles;
DELETE FROM departments;
DELETE FROM countries;

